import React, { useState } from 'react'
import Typography from '@mui/material/Typography';
import Paper from '@mui/material/Paper';
import TextField from '@mui/material/TextField';
import Button from '@mui/material/Button';
//import MUIAppbar from './MUIAppbar';
import axios from 'axios';
export default function AddUser() {

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    phone: '',
    address: ''
  })

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    // console.log(({...formData,[e.target.name]:e.target.value}));
    })
  }

const handleRegister = () => {
  console.log("Form data :", formData);

  axios.post("http://localhost:7000/user/registerUser", formData)
    .then((res) => {
      console.log("Registered user:", res.data);
      alert("Registered user: " + res.data.alluser);
    })
    .catch((error) => {
      console.log(error);
    });
};

  /*const handleRegister = () => {
  const existingusers = JSON.parse(localStorage.getItem('userdetails')) || [];
  console.log(existingusers)

  const allusers = [...existingusers, formData]

  localStorage.setItem('userdetails', JSON.stringify(allusers))
  alert("Registration done!");
}
*/
  return (
    <div>
      {/* <MUIAppbar /> */}
      <Paper elevation={20} style={{ width: "590px", padding: "30px" }}>
        <Typography variant='h4' style={{textAlign:"center", fontFamily:"Times new roman"}}>Add Users</Typography>

        <TextField
          variant='filled'
          type='text'
          label="Name"
          name='name'
          fullWidth
          style={{ marginBottom: "20px", marginLeft: "5px" }}
          onChange={handleChange}
        />

        <TextField
          variant='filled'
          type='email'
          label="Email"
          name='email'
          fullWidth
          style={{ marginBottom: "20px" }}
          onChange={handleChange}
        />

        <TextField
          variant='outlined'
          type='password'
          label="Password"
          name='password'
          fullWidth
          style={{ marginBottom: "20px" }}
          onChange={handleChange}
        />

        <TextField
          variant='standard'
          type='tel'
          label="Phone"
          name='phone'
          fullWidth
          style={{ marginBottom: "20px" }}
          onChange={handleChange}
        />

        <TextField
          variant='filled'
          multiline
          rows={5}
          type='text'
          label="Address"
          name='address'
          fullWidth
          style={{ marginBottom: "20px" }}
          onChange={handleChange}
        />

        <Button variant='contained' fullWidth onClick={handleRegister}>
          Submit
        </Button>

      </Paper>
    </div>
  )
}